import{_ as e,o as t,c as l,a2 as n}from"./chunks/framework.BsAvorgW.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1784136889000}'),i={name:"guide/introduction.md"};function r(s,a,o,d,p,c){return t(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>SelenaProxy 是一个带 WebUI 的 HTTP CONNECT 代理池。它位于调用方和短效代理之间，统一负责提取节点、分配连接、自动轮换和记录用量。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器人 / 脚本  →  SelenaProxy  →  短效代理节点  →  目标接口</span></span>
<span class="line"><span>                  账号鉴权</span></span>
<span class="line"><span>                  自动轮换</span></span>
<span class="line"><span>                  独立统计</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="适合什么场景" tabindex="-1">适合什么场景 <a class="header-anchor" href="#适合什么场景" aria-label="Permalink to &quot;适合什么场景&quot;">​</a></h2><ul><li>多台机器人需要共用同一个代理供应商。</li><li>短效代理过期快，不想在每个程序里重复实现提取和轮换。</li><li>希望为不同服务器分配独立凭据并查看各自用量。</li><li>只允许代理访问指定接口域名和端口。</li></ul><h2 id="请求是怎么走的" tabindex="-1">请求是怎么走的 <a class="header-anchor" href="#请求是怎么走的" aria-label="Permalink to &quot;请求是怎么走的&quot;">​</a></h2><ol><li>调用方向 SelenaProxy 的代理端口发送带账号密码的 CONNECT 请求。</li><li>SelenaProxy 校验账号以及目标域名、端口白名单。</li><li>代理池没有合适节点时，向供应商 API 按需提取。</li><li>SelenaProxy 通过短效节点建立隧道；失败时按设置自动轮换。</li><li>请求结束后记录成功状态、耗时和上下行流量。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>SelenaProxy 是通用 HTTP CONNECT 代理池，不限于某个机器人或插件。只要调用方支持 HTTP 代理即可接入。</p></div><h2 id="默认端口" tabindex="-1">默认端口 <a class="header-anchor" href="#默认端口" aria-label="Permalink to &quot;默认端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>用途</th></tr></thead><tbody><tr><td><code>17891</code></td><td>HTTP CONNECT 代理入口</td></tr><tr><td><code>17892</code></td><td>WebUI 管理后台</td></tr></tbody></table><h2 id="相关项目" tabindex="-1">相关项目 <a class="header-anchor" href="#相关项目" aria-label="Permalink to &quot;相关项目&quot;">​</a></h2><ul><li>代理来源：<a href="https://www.dmdaili.com/" target="_blank" rel="noreferrer">多米代理</a></li><li>使用场景：<a href="https://github.com/Loping151/XutheringWavesUID" target="_blank" rel="noreferrer">XutheringWavesUID</a></li><li>SelenaProxy 源码：<a href="https://github.com/MimoKit/SelenaProxy" target="_blank" rel="noreferrer">MimoKit/SelenaProxy</a></li></ul>`,12)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
